    plan_raw = M.encoded(plan)
    old_cli = ('Name: php\nStatus: ' + modes['php'] + '\nValue: ' + values['php'] +
               '\nBest: ' + values['php'] + '\n')
    recovery = str(job / 'recovery.json')
    files = {'php85_upgrade.py': old_core_fixture('1.0.5'), 'plan.json': plan_raw,
        'plan.sha256': (M.digest(plan_raw) + '\n').encode(), 'timers.json': M.encoded(['apt-daily.timer']),
        'recovery.json': M.encoded(dict(files=plan['files'], old_service='php' + plan['source_branch'] + '-fpm.service', old_cli=old_cli)),
        'alternatives.json': M.encoded(values), 'alternative-modes.json': M.encoded(modes)}
    for index, path in enumerate(sorted(plan['files'])):
        files['configuration-' + str(index)] = backups[path]
    rows, last = [], '0' * 64
    for phase in ('preflight', 'refreshing_indexes', 'plan_sealed', 'downloading_packages', 'installing_packages', 'failed_needs_review'):
        row = dict(time='2026-11-03T01:02:03Z', phase=phase, previous_sha256=last)
        if phase == 'plan_sealed':
            row.update(source=plan['source_branch'], target='8.5', changed_packages=sorted(plan['changes']), plan_sha256=M.digest(plan_raw))
        if phase == 'failed_needs_review':
            row.update(reason='command_failed_apt-get', details={}, recovery=recovery)
        raw = M.encoded(row);rows.append(raw);last = M.digest(raw)
    files['events.jsonl'] = b''.join(rows)
    previous = dict(version='1.0.5', job=str(job), phase='failed_needs_review', event_sha256=last,
                    reason='command_failed_apt-get', details={}, recovery=recovery)
    return files, previous


