        for name,raw in result['previous_files'].items():
            if name=='events.jsonl':self.assertTrue(result['preserved_previous'][name].startswith(raw))
            else:self.assertEqual(result['preserved_previous'][name],raw,name)
        writes={path:raw for path,raw,mode in result['writes']}
        for sapi in ('cli','fpm'):
            migrated=writes['/etc/php/8.5/'+sapi+'/conf.d/99-ubuntu-php85-migration.ini']
            self.assertNotIn(b'mysqli.reconnect',migrated)
        self.assertEqual(len(result['runtime_calls']),2)
        self.assertIn(['/bin/systemctl','stop','apt-daily.timer'],result['commands'])
        self.assertIn(['/bin/systemctl','start','apt-daily.timer'],result['commands'])

